import{_ as a,o as n,c as l,a3 as e}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"春秋","description":"儒家五经之一：鲁国编年史，十二公二百四十二年；通常与《左传》合读。","frontmatter":{"title":"春秋","description":"儒家五经之一：鲁国编年史，十二公二百四十二年；通常与《左传》合读。","category":"guide","aliases":["春秋","春秋经","左传","春秋左传","chunqiu","春秋篇章","春秋目录"],"source":["《春秋》","《左传》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/chunqiu/index.md","filePath":"lizhimingde/sishu-wujing/chunqiu/index.md","lastUpdated":1789987057000}'),h={name:"lizhimingde/sishu-wujing/chunqiu/index.md"};function r(s,i,t,o,u,g){return n(),l("div",null,[...i[0]||(i[0]=[e('<h1 id="春秋" tabindex="-1">春秋 <a class="header-anchor" href="#春秋" aria-label="Permalink to &quot;春秋&quot;">​</a></h1><p>《春秋》是鲁国的编年史，记事自鲁隐公元年（前 722）至鲁哀公十四年（前 481），历<strong>十二公、二百四十二年</strong>。它极简——全书仅一万六千余字，一条常只几个字，因此<strong>必须与传合读</strong>。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><ul><li><strong>经文极简</strong>：如「隐公元年，春，王正月。三月，公及邾仪父盟于蔑。夏五月，郑伯克段于鄢。」——只有事目，没有细节。</li><li><strong>三传</strong>：解释《春秋》的有三部传—— <ul><li><strong>《左传》</strong>：以史事详述经文的背景与过程，是读《春秋》的主干（篇幅远超经文）；</li><li><strong>《公羊传》《谷梁传》</strong>：以问答体阐发「微言大义」，重在义例与褒贬。</li></ul></li><li><strong>「春秋笔法」</strong>：经文的用字极有讲究——同是杀，有「弑」（下杀上）、「诛」、「杀」之别；同是战争，有「伐」「侵」「袭」「围」之分。这是所谓「一字褒贬」。</li></ul><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li><strong>它是中国编年史的起点</strong>：此后两千年的史书体例由此立。</li><li><strong>它是「史」与「义」结合的最早样本</strong>：记史之外，还要通过用字表达评判——「孔子成《春秋》而乱臣贼子惧」。</li><li><strong>《左传》是先秦史料的宝库</strong>：春秋时代的政治、外交、战争、辞令，多赖此书得存。读先秦史，几乎绕不开它。</li><li><strong>成语渊薮</strong>：多行不义必自毙、唇亡齿寒、退避三舍、一鸣惊人、问鼎中原、数典忘祖——都出自《左传》。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li><strong>先读《左传》</strong>，经文作为纲目对照看——只读经文太难进入。</li><li><strong>可从名篇入手</strong>：《郑伯克段于鄢》（隐公元年）、《曹刿论战》（庄公十年）、《烛之武退秦师》（僖公三十年）、《晋灵公不君》（宣公二年）、《子产不毁乡校》（襄公三十一年）。</li><li><strong>留意「春秋笔法」的把戏</strong>：同一件事用不同字眼，读时对比《左传》的叙述，就能看出经文的用意。</li><li><strong>注本</strong>：可参考杨伯峻《春秋左传注》（权威）、杜预《春秋左传集解》。</li></ol><h2 id="篇章" tabindex="-1">篇章 <a class="header-anchor" href="#篇章" aria-label="Permalink to &quot;篇章&quot;">​</a></h2><p>一公一页，共 <strong>12 页</strong>。</p><ol><li><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/chapter-01">隐公（卷1）</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/chapter-02">桓公（卷2）</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/chapter-03">庄公（卷3）</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/chapter-04">闵公（卷4）</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/chapter-05">僖公（卷5）</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/chapter-06">文公（卷6）</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/chapter-07">宣公（卷7）</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/chapter-08">成公（卷8）</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/chapter-09">襄公（卷9）</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/chapter-10">昭公（卷10）</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/chapter-11">定公（卷11）</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/chapter-12">哀公（卷12）</a></li></ol><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><ul><li>各章页当前为骨架（篇名、位置、待整理标记），<strong>原文转录、字词释义与逐章解读后续分批推进</strong>。</li><li>整理方式与《道德经》一致：<strong>一章一页</strong>，目录与文件一一对应。</li><li>参考：杨伯峻《春秋左传注》、杜预《春秋左传集解》</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/shijing/">诗经</a> · <a href="/Dao/lizhimingde/sishu-wujing/shangshu/">尚书</a> · <a href="/Dao/lizhimingde/sishu-wujing/liji/">礼记</a> · <a href="/Dao/lizhimingde/sishu-wujing/yijing">周易</a></li><li>入其门的次第：见<a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li></ul>',15)])])}const m=a(h,[["render",r]]);export{c as __pageData,m as default};
